import {
  anchoredOrder,
  keyBetween,
  placementAt,
  placementForMove,
  placementsForOrder,
  repairAfterRemoval,
  RowPlacement,
  RowPlacements,
  RowTarget,
} from '../row-placements';

import vectors from './__fixtures__/row_placement_vectors.json';

// The vectors are generated by the server's implementation of the rule
// (`libs/collab/src/database/views/row_placement_vectors.rs` in AppFlowy Cloud) and copied here
// unchanged. A row is a number `n` that stands for the row id with the 128-bit value `n`; a
// placement is `[anchor, key]` with anchor 0 for the start slot and the key in hex.

type StoredPlacement = [number, string];
type StoredPlacements = Array<[number, number, string]>;

const rowId = (n: number) => `00000000-0000-0000-0000-${n.toString(16).padStart(12, '0')}`;
const rows = (numbers: number[]) => numbers.map((n) => ({ id: rowId(n) }));
const numbers = (order: Array<{ id: string }>) => order.map((row) => parseInt(row.id.slice(-12), 16));
const bytes = (hex: string) => Uint8Array.from(hex.match(/../g)?.map((byte) => parseInt(byte, 16)) ?? []);
const hex = (key: Uint8Array) => Array.from(key, (byte) => byte.toString(16).padStart(2, '0')).join('');
const writer = (client: string, clock: number) => ({ client: BigInt(client), clock });

function placements(stored: StoredPlacements): RowPlacements {
  return new Map(
    stored.map(([row, anchor, key]) => [rowId(row), { anchor: anchor === 0 ? null : rowId(anchor), key: bytes(key) }])
  );
}

function stored(placement: RowPlacement | null): StoredPlacement | null {
  if (!placement) return null;
  return [placement.anchor === null ? 0 : parseInt(placement.anchor.slice(-12), 16), hex(placement.key)];
}

describe('row placements agree with the shared vectors', () => {
  it('uses the vector format this test understands', () => {
    expect(vectors.format).toBe(1);
  });

  it('generates the same keys', () => {
    expect(vectors.keys.length).toBeGreaterThan(0);

    for (const item of vectors.keys) {
      const key = keyBetween(
        item.lower === null ? null : bytes(item.lower),
        item.upper === null ? null : bytes(item.upper),
        writer(item.client, item.clock)
      );

      expect(hex(key)).toBe(item.key);
    }
  });

  it('reads the same order', () => {
    expect(vectors.orders.length).toBeGreaterThan(0);

    for (const item of vectors.orders) {
      const order = anchoredOrder(rows(item.canonical), placements(item.placements as StoredPlacements));

      expect(numbers(order)).toEqual(item.order);
    }
  });

  it('moves a row the same way', () => {
    expect(vectors.moves.length).toBeGreaterThan(0);

    for (const item of vectors.moves) {
      const canonical = rows(item.canonical);
      const current = placements(item.placements as StoredPlacements);
      const placement = placementForMove(
        canonical,
        current,
        rowId(item.from),
        rowId(item.to),
        writer(item.client, item.clock)
      );

      expect(stored(placement)).toEqual(item.placement);
      if (placement) current.set(rowId(item.from), placement);
      expect(numbers(anchoredOrder(canonical, current))).toEqual(item.order);
    }
  });

  it('puts a row at a position the same way', () => {
    expect(vectors.targets.length).toBeGreaterThan(0);

    for (const item of vectors.targets) {
      const canonical = rows(item.canonical);
      const current = placements(item.placements as StoredPlacements);
      const target = (
        'row' in item.target ? { at: item.target.at, row: rowId(item.target.row as number) } : { at: item.target.at }
      ) as RowTarget;
      const placement = placementAt(canonical, current, rowId(item.row), target, writer(item.client, item.clock));

      expect(stored(placement)).toEqual(item.placement);
      if (placement) current.set(rowId(item.row), placement);
      expect(numbers(anchoredOrder(canonical, current))).toEqual(item.order);
    }
  });

  it('repairs placements after a permanent delete the same way', () => {
    expect(vectors.removals.length).toBeGreaterThan(0);

    for (const item of vectors.removals) {
      const canonical = rows(item.canonical);
      const current = placements(item.placements as StoredPlacements);
      const removed = new Set(item.removed.map(rowId));
      const repair = repairAfterRemoval(canonical, current, removed, writer(item.client, item.clock));

      expect(repair.remove.map((id) => parseInt(id.slice(-12), 16)).sort((a, b) => a - b)).toEqual(item.remove);
      expect(
        repair.write
          .map(([id, placement]) => [parseInt(id.slice(-12), 16), ...(stored(placement) as StoredPlacement)])
          .sort((left, right) => (left[0] as number) - (right[0] as number))
      ).toEqual(item.write);

      repair.remove.forEach((id) => current.delete(id));
      repair.write.forEach(([id, placement]) => current.set(id, placement));

      const remaining = canonical.filter((row) => !removed.has(row.id));

      expect(numbers(anchoredOrder(remaining, current))).toEqual(item.order);
    }
  });
});

// The vectors do not cover the conversion of an order to placements: any keys that give the
// order are right, so it is checked against the order rule the vectors do cover.
describe('placements for a given order', () => {
  const random = (seed: number) => {
    let state = seed;

    return (below: number) => {
      state = (state * 1103515245 + 12345) & 0x7fffffff;
      return state % below;
    };
  };

  const asMap = (written: Array<[string, RowPlacement]>): RowPlacements => new Map(written);

  it('shows the order it was asked for, with no placement for rows that keep their relative order', () => {
    const next = random(3);

    for (let round = 0; round < 300; round++) {
      const size = 1 + next(40);
      const canonical = rows(Array.from({ length: size }, (_, index) => index + 1));
      const target = canonical.map((row) => row.id);

      // A few swaps for some rounds, a full shuffle for the others.
      const swaps = round % 3 === 0 ? size * 2 : next(4);

      for (let swap = 0; swap < swaps; swap++) {
        const left = next(size);
        const right = next(size);

        [target[left], target[right]] = [target[right], target[left]];
      }

      const written = placementsForOrder(canonical, target, writer('7', round));

      expect(written).not.toBeNull();
      expect(anchoredOrder(canonical, asMap(written ?? [])).map((row) => row.id)).toEqual(target);
      // No more rows are placed than the rows off a longest run that is already in order.
      expect((written ?? []).length).toBeLessThan(size);
      (written ?? []).forEach(([, placement]) => expect(placement.key[placement.key.length - 1]).toBe(1));
    }
  });

  it('writes nothing for the canonical order and all but one row for the reverse', () => {
    const canonical = rows([1, 2, 3, 4, 5, 6]);
    const order = canonical.map((row) => row.id);

    expect(placementsForOrder(canonical, order, writer('1', 0))).toEqual([]);
    expect(placementsForOrder(canonical, order.slice().reverse(), writer('1', 0))?.length).toBe(5);
  });

  it('keeps a long run of placed rows in order with short keys', () => {
    const size = 3000;
    const canonical = rows(Array.from({ length: size }, (_, index) => index + 1));
    const target = canonical.map((row) => row.id).reverse();
    const written = placementsForOrder(canonical, target, writer('9', 4)) ?? [];

    expect(anchoredOrder(canonical, asMap(written)).map((row) => row.id)).toEqual(target);
    expect(Math.max(...written.map(([, placement]) => placement.key.length))).toBe(17);
  });

  it('refuses an order that is not exactly the canonical rows', () => {
    const canonical = rows([1, 2, 3]);
    const [one, two, three] = canonical.map((row) => row.id);

    expect(placementsForOrder(canonical, [one, two], writer('1', 0))).toBeNull();
    expect(placementsForOrder(canonical, [one, two, two], writer('1', 0))).toBeNull();
    expect(placementsForOrder(canonical, [one, two, rowId(9)], writer('1', 0))).toBeNull();
    expect(placementsForOrder(canonical, [three, one, two], writer('1', 0))).not.toBeNull();
  });
});
